INSERT INTO pix_movie_deck_entries (deck_key,imdb_id,position,created_at) SELECT 'year-1999', imdb_id, ROW_NUMBER() OVER (ORDER BY CASE WHEN json_extract(attributes_json,'$.deck') = 'year-1999' THEN 0 ELSE 1 END, title COLLATE NOCASE, imdb_id), CAST(strftime('%s','now') AS INTEGER) * 1000 FROM pix_movie_stats WHERE release_year = 1999 AND poster_key <> '' ORDER BY CASE WHEN json_extract(attributes_json,'$.deck') = 'year-1999' THEN 0 ELSE 1 END, title COLLATE NOCASE, imdb_id;
